/**
 * Direct-acquisition funnel, campaign filters and attribution breakdowns.
 *
 * adminActivationFunnelService.test.js covers the original guest funnel; this
 * file covers what was added for paid traffic that lands straight on /register:
 * the second funnel, the utm_* filters, the entry-route breakdown, and the
 * arithmetic guards (zero denominators, out-of-order stages) that a live
 * campaign dashboard would otherwise show as NaN or 250%.
 */
process.env.NODE_ENV = 'development'

// A jest.fn rather than a bare passthrough: the cache key is part of the
// contract here, and inspecting it is the only way to prove two campaigns
// cannot share a cached funnel for the 60s TTL.
jest.mock('../src/services/cacheService', () => ({ wrap: jest.fn(async (_key, fn) => fn()) }))
jest.mock('../src/db', () => ({ query: jest.fn() }))

const { query } = require('../src/db')
const cache = require('../src/services/cacheService')
const adminAnalyticsService = require('../src/services/adminAnalyticsService')

const RANGE = {
  property: 'app.kubus.site',
  from: '2026-07-01T00:00:00.000Z',
  to: '2026-07-30T00:00:00.000Z',
}

const GUEST_STAGES = adminAnalyticsService.ACTIVATION_FUNNEL_STAGES

/// Spelled out rather than imported from the service: the stage list and its
/// order are the contract a dashboard renders, so changing either must fail
/// here rather than silently redefine the funnel.
const DIRECT_STAGES = [
  'app_entry',
  'signup_view',
  'signup_attempt',
  'registration_submitted',
  'account_session_created',
  'onboarding_complete',
  'contribution_started',
  'contribution_submitted',
]

/// Sessions/events/users per stage, for whichever funnel is under test.
function totalsRow(stages, overrides = {}) {
  const row = {}
  for (const stage of stages) {
    row[`${stage}_events`] = 0
    row[`${stage}_sessions`] = 0
    row[`${stage}_users`] = 0
  }
  return { ...row, ...overrides }
}

const GUEST_EMPTY_DURATIONS = {
  map_to_protected_action_seconds: null,
  protected_action_to_session_seconds: null,
  session_to_action_completed_seconds: null,
}

const DIRECT_EMPTY_DURATIONS = {
  entry_to_signup_view_seconds: null,
  signup_view_to_session_seconds: null,
  session_to_contribution_seconds: null,
}

/// Queues the totals + durations responses one call to the funnel consumes.
function mockFunnelQueries(stages, overrides = {}, durations = null) {
  query
    .mockResolvedValueOnce({ rows: [totalsRow(stages, overrides)] })
    .mockResolvedValueOnce({
      rows: [durations || (stages === DIRECT_STAGES ? DIRECT_EMPTY_DURATIONS : GUEST_EMPTY_DURATIONS)],
    })
}

beforeEach(() => {
  query.mockReset()
  // mockClear, not mockReset: the passthrough implementation must survive.
  cache.wrap.mockClear()
})

test('direct_acquisition reports the eight direct stages against app_entry', async () => {
  mockFunnelQueries(DIRECT_STAGES, {
    app_entry_sessions: 500,
    app_entry_events: 520,
    signup_view_sessions: 300,
    signup_attempt_sessions: 180,
    registration_submitted_sessions: 150,
    account_session_created_sessions: 120,
    account_session_created_users: 120,
    onboarding_complete_sessions: 90,
    contribution_started_sessions: 40,
    contribution_submitted_sessions: 25,
    contribution_submitted_users: 25,
  })

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    funnel: 'direct_acquisition',
  })

  expect(data.funnel).toBe('direct_acquisition')
  expect(data.stages.map((s) => s.stage)).toEqual(DIRECT_STAGES)
  expect(data.availableFunnels).toEqual(
    expect.arrayContaining(['guest_discovery', 'direct_acquisition']),
  )

  // Only the direct stages are scanned; the guest stages are not in the batch.
  const [totalsSql, params] = query.mock.calls[0]
  expect(params[4]).toEqual(DIRECT_STAGES)
  expect(params[4]).not.toContain('guest_app_loaded')
  expect(totalsSql).toContain("entry.event_type = 'app_entry'")
  expect(totalsSql).toContain("NULLIF(entry.metadata->>'entry_route', '') = '/register'")
  expect(totalsSql).toMatch(/entry\.utm_campaign[\s\S]*IS NOT NULL[\s\S]*entry\.utm_source[\s\S]*IS NOT NULL/)

  // app_entry is the denominator this funnel exists to have.
  expect(data.totals.entrySessions).toBe(500)
  expect(data.totals.registeredSessions).toBe(120)
  expect(data.totals.onboardedSessions).toBe(90)
  // Registration is not activation: a submitted contribution is.
  expect(data.totals.meaningfullyActivatedSessions).toBe(25)
  expect(data.totals.registrationRate).toBe(0.24)
  expect(data.totals.onboardingRate).toBe(0.75)
  expect(data.totals.activatedFromRegisteredRate).toBe(0.2083)
  expect(data.totals.activatedFromEntryRate).toBe(0.05)

  // Durations are taken from the funnel definition, not one hard-coded set.
  expect(Object.keys(data.medianDurationsSeconds)).toEqual([
    'entryToSignupView', 'signupViewToSession', 'sessionToContribution',
  ])
  const [durationsSql] = query.mock.calls[1]
  expect(durationsSql).toMatch(/first_app_entry/)
  expect(durationsSql).toMatch(/AS entry_to_signup_view_seconds/)
})

test('guest_discovery stays the default and its response is unchanged', async () => {
  mockFunnelQueries(GUEST_STAGES, {
    guest_app_loaded_sessions: 1000,
    guest_app_loaded_events: 1000,
    map_opened_sessions: 900,
    artwork_viewed_sessions: 400,
    protected_action_clicked_sessions: 120,
    auth_gate_viewed_sessions: 110,
    registration_submitted_sessions: 40,
    account_session_created_sessions: 30,
    account_session_created_users: 30,
    pending_action_restored_sessions: 28,
    pending_action_completed_sessions: 25,
  })

  const data = await adminAnalyticsService.getActivationFunnel(RANGE)

  expect(data.funnel).toBe('guest_discovery')
  expect(data.stages.map((s) => s.stage)).toEqual(GUEST_STAGES)
  expect(query.mock.calls[0][1][4]).toEqual(GUEST_STAGES)
  expect(query.mock.calls[0][0]).not.toContain("entry.event_type = 'app_entry'")
  expect(query.mock.calls[0][0]).not.toContain("entry_route', '') = '/register'")

  // The original meanings, preserved: `activatedSessions` is "reached an
  // account session" and `completedSessions` "finished the pending action".
  expect(data.totals.entrySessions).toBe(1000)
  expect(data.totals.activatedSessions).toBe(30)
  expect(data.totals.completedSessions).toBe(25)
  expect(data.totals.activationRate).toBe(0.03)
  expect(data.totals.completionRate).toBeCloseTo(0.8333, 4)
  expect(Object.keys(data.medianDurationsSeconds)).toEqual([
    'mapToProtectedAction', 'protectedActionToSession', 'sessionToActionCompleted',
  ])
})

test('an unknown funnel falls back to guest_discovery instead of failing', async () => {
  mockFunnelQueries(GUEST_STAGES, { guest_app_loaded_sessions: 10 })

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    funnel: 'drop table; --',
  })

  // A stale dashboard link still renders, exactly as an unknown breakdown does.
  expect(data.funnel).toBe('guest_discovery')
  expect(data.stages.map((s) => s.stage)).toEqual(GUEST_STAGES)
  expect(query.mock.calls[0][1][4]).toEqual(GUEST_STAGES)
})

test('each campaign filter binds a parameter and filters the shared base CTE', async () => {
  mockFunnelQueries(GUEST_STAGES)

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    utmCampaign: 'open_call_en_aug_2026',
    utmContent: 'creative_b',
    utmSource: 'meta',
    utmMedium: 'paid_social',
  })

  const [sql, params] = query.mock.calls[0]

  // Bound, never interpolated, and in filter-declaration order after the five
  // fixed parameters.
  expect(params.slice(5)).toEqual(['open_call_en_aug_2026', 'creative_b', 'meta', 'paid_social'])
  expect(sql).toContain("AND COALESCE(NULLIF(utm_campaign, ''), NULLIF(metadata->>'utm_campaign', '')) = $6::text")
  expect(sql).toContain("AND COALESCE(NULLIF(utm_content, ''), NULLIF(metadata->>'utm_content', '')) = $7::text")
  expect(sql).toContain("AND COALESCE(NULLIF(utm_source, ''), NULLIF(metadata->>'utm_source', '')) = $8::text")
  expect(sql).toContain("AND COALESCE(NULLIF(utm_medium, ''), NULLIF(metadata->>'utm_medium', '')) = $9::text")

  // The durations query reads the same CTE with the same parameters, so a
  // campaign's stages can never be reported against another campaign's medians.
  const [durationsSql, durationsParams] = query.mock.calls[1]
  expect(durationsSql).toContain("AND COALESCE(NULLIF(utm_campaign, ''), NULLIF(metadata->>'utm_campaign', '')) = $6::text")
  expect(durationsParams).toEqual(params)

  // Echoed back so an operator sees what they are actually looking at.
  expect(data.filters).toEqual({
    utmCampaign: 'open_call_en_aug_2026',
    utmContent: 'creative_b',
    utmSource: 'meta',
    utmMedium: 'paid_social',
  })
})

test('an unset or blank filter adds no predicate and no parameter', async () => {
  mockFunnelQueries(GUEST_STAGES)

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    utmCampaign: 'open_call_en_aug_2026',
    utmSource: '   ',
  })

  const [sql, params] = query.mock.calls[0]
  expect(params).toHaveLength(6)
  expect(params[5]).toBe('open_call_en_aug_2026')
  expect(sql).toContain("NULLIF(metadata->>'utm_campaign', '')) = $6::text")
  expect(sql).not.toContain("NULLIF(metadata->>'utm_source', '')) = $")
  expect(data.filters.utmSource).toBeNull()
  expect(data.filters.utmMedium).toBeNull()
})

test('campaign filters are part of the cache key', async () => {
  mockFunnelQueries(GUEST_STAGES, { guest_app_loaded_sessions: 10 })
  await adminAnalyticsService.getActivationFunnel({ ...RANGE, utmCampaign: 'summer_art' })

  mockFunnelQueries(GUEST_STAGES, { guest_app_loaded_sessions: 20 })
  await adminAnalyticsService.getActivationFunnel({ ...RANGE, utmCampaign: 'winter_art' })

  const keys = cache.wrap.mock.calls.map(([key]) => key)
  expect(keys).toHaveLength(2)
  // Two campaigns must not share a cached funnel for the 60s TTL.
  expect(keys[0]).not.toBe(keys[1])
  expect(keys[0]).toContain('summer_art')
  expect(keys[1]).toContain('winter_art')
})

test('the funnel and the breakdown are part of the cache key too', async () => {
  mockFunnelQueries(GUEST_STAGES)
  await adminAnalyticsService.getActivationFunnel(RANGE)

  mockFunnelQueries(DIRECT_STAGES)
  await adminAnalyticsService.getActivationFunnel({ ...RANGE, funnel: 'direct_acquisition' })

  const keys = cache.wrap.mock.calls.map(([key]) => key)
  expect(keys[0]).toContain('guest_discovery')
  expect(keys[1]).toContain('direct_acquisition')
  expect(keys[0]).not.toBe(keys[1])
})

test('an empty direct funnel reports zero rates, never NaN or Infinity', async () => {
  mockFunnelQueries(DIRECT_STAGES)

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    funnel: 'direct_acquisition',
  })

  expect(data.totals.entrySessions).toBe(0)
  for (const key of [
    'registrationRate', 'onboardingRate', 'activatedFromRegisteredRate', 'activatedFromEntryRate',
    'activationRate', 'completionRate',
  ]) {
    expect(data.totals[key]).toBe(0)
    expect(Number.isFinite(data.totals[key])).toBe(true)
  }
  for (const stage of data.stages.slice(1)) {
    expect(stage.conversionFromPrevious).toBe(0)
    expect(stage.rawConversionFromPrevious).toBe(0)
    expect(stage.abandonedFromPrevious).toBe(0)
  }
})

test('conversionFromPrevious is clamped to 1 while the raw ratio stays visible', async () => {
  // Stages are not strictly nested: a paid visitor can be counted at
  // signup_view on a session whose app_entry never arrived (an ad blocker, a
  // dropped first beacon), which would otherwise render as 250% conversion.
  mockFunnelQueries(DIRECT_STAGES, {
    app_entry_sessions: 10,
    signup_view_sessions: 25,
    signup_attempt_sessions: 10,
  })

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    funnel: 'direct_acquisition',
  })
  const byStage = Object.fromEntries(data.stages.map((s) => [s.stage, s]))

  expect(byStage.signup_view.conversionFromPrevious).toBe(1)
  expect(byStage.signup_view.rawConversionFromPrevious).toBe(2.5)
  // Consistent with the clamp: nobody was lost at a stage that grew.
  expect(byStage.signup_view.abandonedFromPrevious).toBe(0)

  // A normal step is untouched by the clamp.
  expect(byStage.signup_attempt.conversionFromPrevious).toBe(0.4)
  expect(byStage.signup_attempt.rawConversionFromPrevious).toBe(0.4)

  // The first stage has no predecessor, on either field.
  expect(byStage.app_entry.conversionFromPrevious).toBeNull()
  expect(byStage.app_entry.rawConversionFromPrevious).toBeNull()
})

test('breaks the direct funnel down by entry route', async () => {
  mockFunnelQueries(DIRECT_STAGES, { app_entry_sessions: 300 })
  query.mockResolvedValueOnce({
    rows: [
      {
        dimension: '/register',
        entry_sessions: 200,
        signup_view_sessions: 180,
        registered_sessions: 60,
        onboarded_sessions: 40,
        activated_sessions: 10,
      },
      {
        dimension: '(unknown)',
        entry_sessions: 0,
        signup_view_sessions: 0,
        registered_sessions: 0,
        onboarded_sessions: 0,
        activated_sessions: 0,
      },
    ],
  })

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    funnel: 'direct_acquisition',
    breakdown: 'entry_route',
  })

  expect(data.breakdown).toBe('entry_route')
  expect(data.availableBreakdowns).toEqual(
    expect.arrayContaining(['entry_route', 'utm_medium']),
  )

  const [breakdownSql] = query.mock.calls[2]
  // Metadata only: entry_route is never hoisted to a column.
  expect(breakdownSql).toContain("COALESCE(NULLIF(metadata->>'entry_route', ''), '(unknown)') AS dimension")
  expect(breakdownSql).toContain('LIMIT 25')

  expect(data.breakdownRows[0]).toEqual({
    dimension: '/register',
    entrySessions: 200,
    signupViewSessions: 180,
    registeredSessions: 60,
    onboardedSessions: 40,
    activatedSessions: 10,
    activationRate: 0.05,
  })
  // A landing surface with no entries must not produce a divide-by-zero rate.
  expect(data.breakdownRows[1].activationRate).toBe(0)
})

test('breaks down by utm_medium through the column with a metadata fallback', async () => {
  mockFunnelQueries(GUEST_STAGES, { map_opened_sessions: 100 })
  query.mockResolvedValueOnce({
    rows: [{
      dimension: 'paid_social',
      guest_sessions: 90,
      map_sessions: 80,
      protected_action_sessions: 20,
      activated_sessions: 8,
      completed_sessions: 6,
    }],
  })

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    breakdown: 'utm_medium',
  })

  const [breakdownSql] = query.mock.calls[2]
  expect(breakdownSql).toContain("COALESCE(NULLIF(utm_medium, ''), NULLIF(metadata->>'utm_medium', ''), '(none)') AS dimension")
  expect(data.breakdownRows[0].dimension).toBe('paid_social')
  expect(data.breakdownRows[0].activationRate).toBe(0.1)
})

test('rows written before the campaign columns were hoisted still group and filter', async () => {
  mockFunnelQueries(GUEST_STAGES, { map_opened_sessions: 40 })
  query.mockResolvedValueOnce({
    rows: [{
      dimension: 'legacy_campaign',
      guest_sessions: 40,
      map_sessions: 40,
      protected_action_sessions: 10,
      activated_sessions: 4,
      completed_sessions: 2,
    }],
  })

  const data = await adminAnalyticsService.getActivationFunnel({
    ...RANGE,
    breakdown: 'campaign',
    utmSource: 'meta',
  })

  const [sql] = query.mock.calls[0]
  // The base CTE reads the real columns rather than NULL placeholders...
  expect(sql).not.toContain('NULL::text AS utm_campaign')
  expect(sql).not.toContain('NULL::text AS utm_source')
  // ...and every campaign read falls back to metadata, so rows written before
  // migration 028 hoisted the columns are still matched. This is also the exact
  // expression migration 087 indexes.
  expect(sql).toContain("COALESCE(NULLIF(utm_source, ''), NULLIF(metadata->>'utm_source', ''))")

  const [breakdownSql] = query.mock.calls[2]
  expect(breakdownSql).toContain("COALESCE(NULLIF(utm_campaign, ''), NULLIF(metadata->>'utm_campaign', ''), '(none)')")
  expect(data.breakdownRows[0].dimension).toBe('legacy_campaign')
})
